import { Module } from "@nestjs/common"
import { OnGatewayConnection, OnGatewayDisconnect, OnGatewayInit, WebSocketGateway } from "@nestjs/websockets"
import { io } from "socket.io-client"
import type { Socket } from "socket.io"

@WebSocketGateway()
class PresenceGateway implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect {
    online = 0
    afterInit() { console.log("Gateway tayyor") }
    handleConnection(client: Socket) { this.online++; console.log(`+ ulandi (${client.handshake.auth.name}), online: ${this.online}`) }
    handleDisconnect(client: Socket) { this.online--; console.log(`- uzildi (${client.handshake.auth.name}), online: ${this.online}`) }
}

@Module({ providers: [PresenceGateway] })
class AppModule {}

const wait = (ms: number) => new Promise(r => setTimeout(r, ms))

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    const a = io(url, { transports: ["websocket"], auth: { name: "Ali" } })
    await wait(100)
    const b = io(url, { transports: ["websocket"], auth: { name: "Vali" } })
    await wait(100)
    a.close()
    await wait(100)
    b.close()
    await wait(100)
    await http.close()
}
main()

import { Module } from "@nestjs/common"
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway } from "@nestjs/websockets"
import { io } from "socket.io-client"
import type { Socket } from "socket.io"

@WebSocketGateway()
class TimerGateway {
    @SubscribeMessage("countdown")
    countdown(@MessageBody() from: number, @ConnectedSocket() client: Socket) {
        let n = from
        const t = setInterval(() => {
            client.emit("tick", n)
            if (n-- === 0) { clearInterval(t); client.emit("done", "Boshlandi!") }
        }, 20)
    }
}

@Module({ providers: [TimerGateway] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const socket = io(await http.app.getUrl(), { transports: ["websocket"] })
    socket.on("tick", (n: number) => console.log("tick:", n))
    socket.on("done", async (msg: string) => { console.log(msg); socket.close(); await http.close() })
    socket.emit("countdown", 3)
}
main()

