import { Body, Controller, Module, Post } from "@nestjs/common"
import { WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import { io } from "socket.io-client"
import type { Server } from "socket.io"

@WebSocketGateway()
class NotificationsGateway {
    @WebSocketServer() server: Server
    broadcast(message: string) { this.server.emit("notification", message) }
}

@Controller("orders")
class OrdersController {
    constructor(private readonly notifications: NotificationsGateway) {}
    @Post() create(@Body("item") item: string) {
        this.notifications.broadcast(`Yangi buyurtma: ${item}`)
        return { created: true }
    }
}

@Module({ controllers: [OrdersController], providers: [NotificationsGateway] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const admin = io(await http.app.getUrl(), { transports: ["websocket"] })
    await new Promise<void>(r => admin.on("connect", () => r()))
    const got = new Promise(r => admin.on("notification", (m: string) => { console.log("Admin panelga keldi:", m); r(null) }))
    await http.post("/orders", { item: "Samsa x10" })
    await got
    admin.close()
    await http.close()
}
main()

