import { Module } from "@nestjs/common"
import { OnGatewayConnection, WebSocketGateway } from "@nestjs/websockets"
import type { Socket } from "socket.io"
import { io } from "socket.io-client"

@WebSocketGateway()
class GuardedGateway implements OnGatewayConnection {
    handleConnection(client: Socket) {
        if (client.handshake.auth?.token !== "ok") {
            client.emit("error-message", "Token yo'q — ulanish yopiladi")
            client.disconnect(true)
        }
    }
}
@Module({ providers: [GuardedGateway] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const s = io(await http.app.getUrl(), { transports: ["websocket"], auth: {} })
    s.on("error-message", (m: string) => console.log("server:", m))
    const reason = await new Promise(r => s.on("disconnect", r))
    console.log("uzilish sababi:", reason)
    s.close(); await http.close()
}
main()

