import { Module, OnModuleDestroy } from "@nestjs/common"
import { OnGatewayInit, WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import type { Server } from "socket.io"
import { io } from "socket.io-client"

@WebSocketGateway()
class TickerGateway implements OnGatewayInit, OnModuleDestroy {
    @WebSocketServer() server: Server
    private timer?: NodeJS.Timeout
    private price = 12650
    afterInit() { this.timer = setInterval(() => this.server.emit("usd", (this.price += 5)), 20) }
    onModuleDestroy() { clearInterval(this.timer) }
}
@Module({ providers: [TickerGateway] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const s = io(await http.app.getUrl(), { transports: ["websocket"] })
    const received: number[] = []
    await new Promise<void>(r => s.on("usd", (p: number) => { received.push(p); if (received.length === 3) r() }))
    console.log("3 ta yangilanish oldi, o'sib bormoqda:", received[0] < received[1] && received[1] < received[2])
    s.close(); await http.close()
}
main()

