import { Module } from "@nestjs/common"
import { ConnectedSocket, SubscribeMessage, WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import type { Server, Socket as ServerSocket } from "socket.io"
import { io, Socket } from "socket.io-client"

@WebSocketGateway() class G {
    @WebSocketServer() server!: Server
    @SubscribeMessage("toAll") all() { this.server.emit("msg", "hammaga"); return "ok" }
    @SubscribeMessage("toMe") me(@ConnectedSocket() c: ServerSocket) { c.emit("msg", "faqat senga"); return "ok" }
}
@Module({ providers: [G] }) class AppModule {}
const connect = (url: string) => new Promise<Socket>(r => { const s = io(url, { transports: ["websocket"] }); s.on("connect", () => r(s)) })

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    const [a, b] = await Promise.all([connect(url), connect(url)])
    const got: string[] = []
    a.on("msg", m => got.push(`A: ${m}`)); b.on("msg", m => got.push(`B: ${m}`))
    await a.emitWithAck("toMe")
    await a.emitWithAck("toAll")
    await new Promise(r => setTimeout(r, 50))
    console.log(got.sort())
    a.close(); b.close(); await http.close()
}
main()

