import type { Server, Socket } from "socket.io"

@WebSocketGateway()
class DmGateway implements OnGatewayConnection {
    @WebSocketServer() server: Server
    handleConnection(c: Socket) { c.join(`user:${c.handshake.auth.userId}`) }
    @SubscribeMessage("dm")
    dm(@MessageBody() d: { to: number; text: string }, @ConnectedSocket() c: Socket) {
        this.server.to(`user:${d.to}`).emit("dm", { from: c.handshake.auth.userId, text: d.text })
        return "yuborildi"
    }
}

@Module({ providers: [DmGateway] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
