import { Module } from "@nestjs/common"
import { OnGatewayConnection, OnGatewayDisconnect, WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import { io, Socket as ClientSocket } from "socket.io-client"
import type { Server, Socket } from "socket.io"

@WebSocketGateway()
class OnlineGateway implements OnGatewayConnection, OnGatewayDisconnect {
    @WebSocketServer() server: Server
    private online = new Map<string, string>()
    handleConnection(c: Socket) { this.online.set(c.id, c.handshake.auth.name); this.publish() }
    handleDisconnect(c: Socket) { this.online.delete(c.id); this.publish() }
    private publish() { this.server.emit("online", [...this.online.values()]) }
}

