import { Module } from "@nestjs/common"
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway } from "@nestjs/websockets"
import type { Socket as ServerSocket } from "socket.io"
import { io, Socket } from "socket.io-client"

@WebSocketGateway() class Share {
    @SubscribeMessage("share") share(@MessageBody() f: { name: string; size: number; mime: string }, @ConnectedSocket() c: ServerSocket) {
        const allowed = ["image/png", "application/pdf"]
        if (!allowed.includes(f.mime) || f.size > 5_000_000) return { ok: false, reason: "tur yoki hajm ruxsat etilmagan" }
        c.broadcast.emit("file", { ...f, url: `/files/${encodeURIComponent(f.name)}` })
        return { ok: true }
    }
}
@Module({ providers: [Share] }) class AppModule {}
const connect = (url: string) => new Promise<Socket>(r => { const s = io(url, { transports: ["websocket"] }); s.on("connect", () => r(s)) })

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    const [a, b] = await Promise.all([connect(url), connect(url)])
    const got = new Promise(r => b.once("file", r))
    console.log(await a.emitWithAck("share", { name: "shartnoma.pdf", size: 240_000, mime: "application/pdf" }), "→ B oldi:", await got)
    console.log(await a.emitWithAck("share", { name: "virus.exe", size: 100, mime: "application/x-msdownload" }))
    a.close(); b.close(); await http.close()
}
main()

