import { Module } from "@nestjs/common"
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import type { Server, Socket as ServerSocket } from "socket.io"
import { io, Socket } from "socket.io-client"

@WebSocketGateway() class Track {
    @WebSocketServer() server!: Server
    @SubscribeMessage("watch") watch(@MessageBody() orderId: number, @ConnectedSocket() c: ServerSocket) { c.join(`order:${orderId}`); return true }
    @SubscribeMessage("location") loc(@MessageBody() b: { orderId: number; lat: number; lng: number }) { this.server.to(`order:${b.orderId}`).emit("courier", { lat: b.lat, lng: b.lng }); return true }
}
@Module({ providers: [Track] }) class AppModule {}
const connect = (url: string) => new Promise<Socket>(r => { const s = io(url, { transports: ["websocket"] }); s.on("connect", () => r(s)) })

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    const [customer, courier] = await Promise.all([connect(url), connect(url)])
    await customer.emitWithAck("watch", 51)
    const points: object[] = []
    customer.on("courier", p => points.push(p))
    for (const [lat, lng] of [[41.311, 69.279], [41.315, 69.285]]) await courier.emitWithAck("location", { orderId: 51, lat, lng })
    await new Promise(r => setTimeout(r, 30))
    console.log("mijoz ko'rdi:", points)
    customer.close(); courier.close(); await http.close()
}
main()

import { Module } from "@nestjs/common"
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import type { Server, Socket as ServerSocket } from "socket.io"
import { io, Socket } from "socket.io-client"

@WebSocketGateway() class Orders {
    @WebSocketServer() server!: Server
    @SubscribeMessage("follow") follow(@MessageBody() id: number, @ConnectedSocket() c: ServerSocket) { c.join(`order:${id}`); return true }
    @SubscribeMessage("status") status(@MessageBody() b: { id: number; status: string }) { this.server.to(`order:${b.id}`).emit("status", b.status); return true }
}
@Module({ providers: [Orders] }) class AppModule {}
const connect = (url: string) => new Promise<Socket>(r => { const s = io(url, { transports: ["websocket"] }); s.on("connect", () => r(s)) })

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    const [customer, kitchen] = await Promise.all([connect(url), connect(url)])
    await customer.emitWithAck("follow", 7)
    const seen: string[] = []
    const done = new Promise<void>(r => customer.on("status", (st: string) => { seen.push(st); if (st === "yetkazildi") r() }))
    for (const st of ["qabul qilindi", "tayyorlanmoqda", "yo'lda", "yetkazildi"]) await kitchen.emitWithAck("status", { id: 7, status: st })
    await done
    console.log(seen.join(" → "))
    customer.close(); kitchen.close(); await http.close()
}
main()

import { Module } from "@nestjs/common"
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway } from "@nestjs/websockets"
import type { Socket as ServerSocket } from "socket.io"
import { io } from "socket.io-client"

@WebSocketGateway() class Chat {
    @SubscribeMessage("input") input(@MessageBody() raw: string, @ConnectedSocket() c: ServerSocket) {
        if (!raw.startsWith("/")) return `${c.data.nick ?? "anonim"}: ${raw}`
        const [cmd, ...args] = raw.slice(1).split(" ")
        switch (cmd) {
            case "nick": c.data.nick = args[0]; return `taxallus: ${args[0]}`
            case "help": return "buyruqlar: /nick <ism>, /help"
            default: return `noma'lum buyruq: /${cmd}`
        }
    }
}
@Module({ providers: [Chat] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const s = io(await http.app.getUrl(), { transports: ["websocket"] })
    for (const t of ["salom", "/help", "/nick Dilnoza", "hammaga salom", "/dance"]) console.log(`> ${t}\n  ${await s.emitWithAck("input", t)}`)
    s.close(); await http.close()
}
main()

import { Module } from "@nestjs/common"
import { MessageBody, SubscribeMessage, WebSocketGateway, WebSocketServer } from "@nestjs/websockets"
import type { Server } from "socket.io"
import { io, Socket } from "socket.io-client"

let seq = 0
@WebSocketGateway() class Chat { @WebSocketServer() server!: Server; @SubscribeMessage("say") say(@MessageBody() text: string) { const m = { seq: ++seq, text }; this.server.emit("message", m); return m.seq } }
@Module({ providers: [Chat] }) class AppModule {}
const connect = (url: string) => new Promise<Socket>(r => { const s = io(url, { transports: ["websocket"] }); s.on("connect", () => r(s)) })

async function main() {
    const http = await testApp(AppModule)
    const url = await http.app.getUrl()
    const [a, reader] = await Promise.all([connect(url), connect(url)])
    const got: { seq: number; text: string }[] = []
    reader.on("message", m => got.push(m))
    await Promise.all(["uch", "bir", "ikki"].map(t => a.emitWithAck("say", t)))
    await new Promise(r => setTimeout(r, 50))
    console.log("seq bo'yicha:", got.sort((x, y) => x.seq - y.seq).map(m => m.seq), "| hammasi keldi:", got.length === 3)
    a.close(); reader.close(); await http.close()
}
main()
